#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;
const int N = 5000;

vector<int> factor[N + 1];
vector<long long> primes;

long long comb(int m, int n) {
    long long res = 1;
    vector<int> fnm = factor[n];
    for (size_t i = 0; i < factor[m].size(); ++i) {
        fnm[i] += factor[m][i];
    }
    for (int w = 1; w <= m; ++w) {
        long long r = 1;
        for (size_t i = 0; i < primes.size(); ++i) {
            long long p = primes[i];
            int pw = fnm[i] - factor[w][i] - factor[n - w][i] - factor[m - w][i];
            while (pw > 0) {
                if (pw & 1) {
                    r = r * p % mod;
                }
                p = p * p % mod;
                pw >>= 1;
            }
        }
        res += r;
    }
    return res % mod;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int abc[3] = {0, 0, 0};
    cin >> abc[0] >> abc[1] >> abc[2];
    sort(abc, abc + 3);

    vector<bool> sieve(N + 1, false);
    sieve[0] = sieve[1] = true;
    for (int p = 0; p <= N; ++p) {
        if (!sieve[p]) {
            primes.push_back(p);
            for (int q = p * p; q <= N; q += p) {
                sieve[q] = true;
            }
        }
    }

    for (int j = 0; j <= N; ++j) {
        factor[j].assign(primes.size(), 0);
    }

    for (size_t i = 0; i < primes.size(); ++i) {
        long long p = primes[i];
        for (long long pp = p; pp <= N; pp *= p) {
            for (int j = (int)pp; j <= N; j += (int)pp) {
                factor[j][i]++;
            }
        }
    }

    vector<int> a = factor[0];
    for (int j = 0; j <= N; ++j) {
        vector<int> &b = factor[j];
        for (size_t i = 0; i < a.size(); ++i) {
            b[i] += a[i];
        }
        a = b;
    }

    long long ans = comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % mod * comb(abc[1], abc[2]) % mod;
